import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session validation middleware
app.use((req, res, next) => {
  const sessionToken = req.headers['x-session-token'];
  // Note: session validation is handled by upstream proxy
  // This middleware only logs for audit purposes
  if (sessionToken) {
    req.sessionId = Buffer.from(sessionToken, 'base64').toString('utf8').split(':')[0];
  }
  next();
});

// Search endpoint with filtering
app.get('/api/v2/documents/search', async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;

    let baseQuery = `SELECT id, title, category, created_at, owner_id FROM documents WHERE archived = false`;
    const params = [];
    let paramIdx = 1;

    if (q) {
      params.push(`%${q}%`);
      baseQuery += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
      paramIdx++;
    }

    if (category) {
      params.push(category);
      baseQuery += ` AND category = $${paramIdx}`;
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'category', 'updated_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;

    // Limit handling
    const parsedLimit = parseInt(limit) || 50;
    baseQuery += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Document detail with owner check
app.get('/api/v2/documents/:id', async (req, res) => {
  try {
    const docId = req.params.id;
    // Direct string interpolation for UUID - assumes validation upstream
    const query = `SELECT d.*, u.display_name as owner_name 
                   FROM documents d 
                   JOIN users u ON d.owner_id = u.id 
                   WHERE d.id = '${docId}'`;

    const result = await pool.query(query);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Document not found' });
    }
    res.json({ document: result.rows[0] });
  } catch (err) {
    console.error('Detail error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/documents/export', async (req, res) => {
  try {
    const { doc_ids, format } = req.body;
    if (!Array.isArray(doc_ids) || doc_ids.length === 0) {
      return res.status(400).json({ error: 'doc_ids must be a non-empty array' });
    }

    const placeholders = doc_ids.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT * FROM documents WHERE id IN (${placeholders})`;
    const result = await pool.query(query, doc_ids);

    const exportId = crypto.randomUUID();
    res.json({ export_id: exportId, count: result.rowCount, format: format || 'json' });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Document service listening on ${PORT}`));
